import { defineConfig } from 'vitest/config'

// One root config, one project per package. Tests never boot Payload or a
// database: they inject fakes. `tests/parity` in the stats package compares
// the TypeScript engine against fixtures generated by Python gbstats
// (scripts/gbstats-parity) and is the correctness gate for the whole repo.
export default defineConfig({
  esbuild: { jsx: 'automatic' },
  test: {
    projects: [
      {
        test: {
          name: 'stats',
          root: 'packages/stats',
          globals: true,
          environment: 'node',
          include: ['tests/**/*.test.ts'],
        },
      },
      {
        test: {
          name: 'plugin',
          root: 'packages/plugin',
          globals: true,
          environment: 'node',
          include: ['tests/**/*.test.ts', 'tests/**/*.test.tsx'],
        },
      },
    ],
    coverage: {
      provider: 'v8',
      reporter: ['text', 'json', 'html'],
      include: ['packages/*/src/**/*.{ts,tsx}'],
      exclude: ['**/*.d.ts', '**/exports/**'],
    },
  },
})
